('724a373c-77cd-58d8-808e-788c2e93c5ad', '11d40fdb-885f-55ca-93b8-a2d6d110bb68', 'The current through each component', 'A', false, 0),
('b9d10876-70c2-5c22-a0c8-d1b4a65f5883', '11d40fdb-885f-55ca-93b8-a2d6d110bb68', 'The p.d. across each component', 'B', true, 1),
('d755c2dc-4536-5aa7-8274-a8b7389c403a', '11d40fdb-885f-55ca-93b8-a2d6d110bb68', 'The charge on each component', 'C', false, 2),
('94f95d27-6083-5032-b954-884e411c9331', '11d40fdb-885f-55ca-93b8-a2d6d110bb68', 'The energy in each component', 'D', false, 3),
('5397a01f-43f4-5cbd-a8ee-5e5f83dcfce8', '0e69f5ae-d048-5b7b-9da6-16fb6844e87b', 'Both totals increase', 'A', false, 0),
('04151f90-5e60-5d2f-b120-a134989362cf', '0e69f5ae-d048-5b7b-9da6-16fb6844e87b', 'Both totals decrease', 'B', false, 1),
('df6ce901-4b7b-5493-aae9-91c53bd33474', '0e69f5ae-d048-5b7b-9da6-16fb6844e87b', 'Total resistance decreases for resistors; total capacitance increases for capacitors', 'C', true, 2),
('07ab8fb2-d2d5-567d-94ee-6eb1931bf193', '0e69f5ae-d048-5b7b-9da6-16fb6844e87b', 'Total resistance increases; total capacitance decreases', 'D', false, 3),
('273a55fd-09b7-5f50-bb36-3d1ce97ec804', '7d4678da-6c43-5736-a8af-9aabc94c32d7', 'Ω = V A⁻¹ and F = C V⁻¹', 'A', true, 0),
('ea3ee4f6-2297-5f30-8b4d-1772091ab4a2', '7d4678da-6c43-5736-a8af-9aabc94c32d7', 'Ω = A V⁻¹ and F = V C⁻¹', 'B', false, 1),
('6b91c42b-1392-502e-a1a7-0bc4997b144c', '7d4678da-6c43-5736-a8af-9aabc94c32d7', 'Ω = V A and F = C V', 'C', false, 2),
('1fcb03ba-311a-5592-a0a7-64f1d3421354', '7d4678da-6c43-5736-a8af-9aabc94c32d7', 'Ω = J s⁻¹ and F = J C⁻¹', 'D', false, 3),
('5a6c724d-b526-5e81-b52e-4a1cac4a45f3', 'ba5a50da-cd27-58d4-86ad-cc7b54b2a065', 'Resistors: p.d. Capacitors: p.d.', 'A', false, 0),
('29d88e78-9f00-5115-8906-cb98ab1298f3', 'ba5a50da-cd27-58d4-86ad-cc7b54b2a065', 'Resistors: current. Capacitors: p.d.', 'B', false, 1),
('4542e56c-b6f4-5b97-b04c-bba0261ef71a', 'ba5a50da-cd27-58d4-86ad-cc7b54b2a065', 'Resistors: power. Capacitors: energy.', 'C', false, 2),
('25eccc7e-73ec-54b5-a0f8-1de69a7db747', 'ba5a50da-cd27-58d4-86ad-cc7b54b2a065', 'Resistors: current. Capacitors: charge.', 'D', true, 3),
('cc7e030a-bf14-5372-b5d5-d65a9fcef110', '569ba7c8-2f19-51b2-a884-8180778bea87', 'Both allow a steady current', 'A', false, 0),
('fc452d4d-0552-51c6-8d0d-332b281f0b17', '569ba7c8-2f19-51b2-a884-8180778bea87', 'A steady current can pass through a resistor, but a capacitor stops a steady current once charged', 'B', true, 1),
('aad18efc-3b05-5a14-9bbf-fdd87ab1df0f', '569ba7c8-2f19-51b2-a884-8180778bea87', 'Neither allows a steady current', 'C', false, 2),
('3b42f900-7bb9-555f-bfdb-2024fd4970b4', '569ba7c8-2f19-51b2-a884-8180778bea87', 'A capacitor allows a steady current, but a resistor does not', 'D', false, 3),
('b014c587-7075-52b8-9cff-b62fe779c882', '1a3083f6-5170-5e87-9b61-06916e4e14c2', 'Capacitor: zero. Resistor: equal to the e.m.f.', 'A', false, 0),
('fc234b42-2b62-5cf4-93cc-bf70126c1f54', '1a3083f6-5170-5e87-9b61-06916e4e14c2', 'Each has half the e.m.f.', 'B', false, 1),
('32981b63-36ce-563d-9d4a-03ac936b5672', '1a3083f6-5170-5e87-9b61-06916e4e14c2', 'Capacitor: equal to the e.m.f. Resistor: zero.', 'C', true, 2),
('11fdc171-8efb-510c-956c-f72d91406e24', '1a3083f6-5170-5e87-9b61-06916e4e14c2', 'Both equal the e.m.f.', 'D', false, 3),
('fe925700-d9cc-5345-ad9c-a6f19c260360', '7935afba-7d52-5acd-bf92-1c958c84cc89', 'Capacitance doubles; resistance halves', 'A', true, 0),
('bc3edea2-df80-5ab8-92d7-3a63c80d07fe', '7935afba-7d52-5acd-bf92-1c958c84cc89', 'Capacitance halves; resistance doubles', 'B', false, 1),
('9757c9a6-d1fc-5b3f-846a-200c12a3136c', '7935afba-7d52-5acd-bf92-1c958c84cc89', 'Both double', 'C', false, 2),
('ce848d1b-9a54-5d95-8e45-20efc53aa39d', '7935afba-7d52-5acd-bf92-1c958c84cc89', 'Both halve', 'D', false, 3),
('823c840e-bfde-5ca0-9784-25fc86c4bae8', '99d30a43-ddde-57bc-a1ad-9f39bc56d513', 'All three in series', 'A', false, 0),
('7bf70e8a-ce92-59fb-a543-097e2f23b1e2', '99d30a43-ddde-57bc-a1ad-9f39bc56d513', 'Two in series, in parallel with the third', 'B', false, 1),
('e44c5c6e-38a7-57c9-a1d6-4b0168c96d60', '99d30a43-ddde-57bc-a1ad-9f39bc56d513', 'Two in parallel, in series with the third', 'C', false, 2),
('de1e932e-023c-5e30-8ef6-1c3c64c52d82', '99d30a43-ddde-57bc-a1ad-9f39bc56d513', 'All three in parallel', 'D', true, 3),
('c97c85ca-4497-5968-8e0e-d775f1399f32', 'da0735fc-84af-59a3-bec4-e0ae056b96c0', 'Capacitor: equal to the e.m.f. Resistor: zero.', 'A', false, 0),
('49b1ac5e-f363-5aab-803c-dfc9906141d8', 'da0735fc-84af-59a3-bec4-e0ae056b96c0', 'Capacitor: zero. Resistor: equal to the e.m.f.', 'B', true, 1),
('a9913649-dd8f-5868-ae89-3ac615bc5c0f', 'da0735fc-84af-59a3-bec4-e0ae056b96c0', 'Each has half the e.m.f.', 'C', false, 2),
('61cdfee8-80cf-535d-9b87-57bf0495b584', 'da0735fc-84af-59a3-bec4-e0ae056b96c0', 'Both are zero', 'D', false, 3),
('054509ef-d60a-5564-9eda-046393ef2fa1', '7a59ad22-774d-5812-9627-ef2c143cb391', 'Capacitors in parallel and resistors in series', 'A', false, 0),
('e9b59572-db76-5607-88cb-4d74d771c914', '7a59ad22-774d-5812-9627-ef2c143cb391', 'Capacitors in series and resistors in series', 'B', false, 1),
('3447b27e-a641-5b1b-a9f5-b554b90d560b', '7a59ad22-774d-5812-9627-ef2c143cb391', 'Capacitors in series and resistors in parallel', 'C', true, 2),
('87f67171-d4d5-5766-95a1-14c80c363a8f', '7a59ad22-774d-5812-9627-ef2c143cb391', 'Capacitors in parallel and resistors in parallel', 'D', false, 3),
('e9dd350f-0d06-58a1-b8af-e2938d64b861', 'e6b048e1-ca98-5acf-97db-fadd0696375b', 'The capacitor''s dielectric is an insulator, so charge builds up on its plates until their p.d. opposes the supply', 'A', true, 0),
('2804ea9e-8833-56dc-a8e0-54c6a251cb55', 'e6b048e1-ca98-5acf-97db-fadd0696375b', 'The capacitor''s resistance gradually increases to infinity', 'B', false, 1),
('992b967e-5a2f-504f-806c-b93c910c1d5e', 'e6b048e1-ca98-5acf-97db-fadd0696375b', 'The capacitor uses up the current', 'C', false, 2),
('80449d48-d17f-556a-a998-3435446a2f55', 'e6b048e1-ca98-5acf-97db-fadd0696375b', 'The resistor stores charge, so it keeps conducting', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('f38d554c-1d48-5fa6-8893-159bbe9fdbf4', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 7, 7, 'A 2.0 µF and a 3.0 µF capacitor are in parallel, and the pair is in series with a 5.0 µF capacitor. Calculate the combined capacitance, in µF.', NULL, 1, 'numeric'::answer_type, '2.5', 'µF', false, NULL, false, ARRAY['2.5e-6']::text[], 'Parallel pair: 2.0 + 3.0 = 5.0 µF. In series with 5.0 µF: C = 5.0 × 5.0 ÷ 10 = 2.5 µF. Mark scheme (2 marks). C1: reduce the parallel pair first. A1: C = 2.5 µF.', 2),
('946bb76a-8536-5d95-a7af-bf19921efeaa', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 8, 8, 'A branch of two 4.0 µF capacitors in series has a 2.0 µF capacitor connected across it. What is the total, in µF?', NULL, 1, 'numeric'::answer_type, '4', 'µF', false, NULL, false, ARRAY['4e-6']::text[], 'Series pair: 4.0 ÷ 2 = 2.0 µF. In parallel with 2.0 µF: C = 2.0 + 2.0 = 4.0 µF. Mark scheme (2 marks). C1: series pair then parallel. A1: C = 4.0 µF.', 2),
('a65123eb-042f-5495-9153-1df7a1aaffba', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 9, 9, 'What is the best first step when finding the combined capacitance of a network?', NULL, 1, 'multiple_choice'::answer_type, 'Replace each group that is clearly in series or clearly in parallel with a single equivalent capacitor', NULL, false, NULL, false, NULL, 'Simplify the innermost groups step by step until one capacitor remains. Mark scheme (1 mark). B1: C (Replace each group that is clearly in series or clearly in parallel with a single equivalent capacitor).', 1),
('aff7b284-e6da-572f-a2d4-afddffcefe4e', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 10, 10, 'Three 3.0 µF capacitors are connected so that two are in series and that pair is in parallel with the third. Calculate the combined capacitance, in µF.', NULL, 1, 'numeric'::answer_type, '4.5', 'µF', false, NULL, false, ARRAY['4.5e-6']::text[], 'Series pair: 3.0 ÷ 2 = 1.5 µF. Total: 1.5 + 3.0 = 4.5 µF. Mark scheme (2 marks). C1: series pair then add. A1: C = 4.5 µF.', 2),
('5984f026-5f55-565e-ba0d-9a7f911cbea7', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 11, 11, 'A 3.0 µF capacitor is connected in series with a parallel pair of 3.0 µF capacitors. Find the equivalent capacitance, in µF.', NULL, 1, 'numeric'::answer_type, '2', 'µF', false, NULL, false, ARRAY['2e-6']::text[], 'Parallel pair: 6.0 µF. In series with 3.0 µF: C = 6.0 × 3.0 ÷ 9.0 = 2.0 µF. Mark scheme (2 marks). C1: parallel pair then series. A1: C = 2.0 µF.', 2),
('16f1da41-33a9-50d0-9eed-4bb41f2938a8', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 12, 12, 'Three identical capacitors can be connected in four different ways. Which arrangement gives the smallest combined capacitance?', NULL, 1, 'multiple_choice'::answer_type, 'All three in series', NULL, false, NULL, false, NULL, 'All in series gives C/3, the smallest of C/3, 2C/3, 1.5C and 3C. Mark scheme (1 mark). B1: A (All three in series).', 1),
('e1c7808d-75b2-5525-96c1-28237744dfa8', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 13, 13, 'A network has two 10 µF capacitors in parallel with each other, and also in parallel with a branch made of two 10 µF capacitors in series. Calculate the combined capacitance, in µF.', NULL, 1, 'numeric'::answer_type, '25', 'µF', false, NULL, false, ARRAY['2.5e-5']::text[], 'Series branch: 10 ÷ 2 = 5.0 µF. Total: 10 + 10 + 5.0 = 25 µF. Mark scheme (2 marks). C1: series branch then add parallel paths. A1: C = 25 µF.', 2),
('cb785bbd-cd0f-53b7-b215-8abfb3768012', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 14, 14, 'Two 2.0 µF capacitors are to give a combined capacitance of 1.0 µF. How must they be connected?', NULL, 1, 'multiple_choice'::answer_type, 'In series', NULL, false, NULL, false, NULL, 'Two equal capacitors in series give half the value. Mark scheme (1 mark). B1: D (In series).', 1),
('7751db74-250c-5700-b79d-c638b4b9b7d4', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 15, 15, 'Two 1.0 µF capacitors in parallel are connected in series with another two 1.0 µF capacitors in parallel. Calculate the combined capacitance, in µF.', NULL, 1, 'numeric'::answer_type, '1', 'µF', false, NULL, false, ARRAY['1e-6']::text[], 'Each parallel pair is 2.0 µF; two in series give 2.0 ÷ 2 = 1.0 µF. Mark scheme (2 marks). C1: reduce each pair. A1: C = 1.0 µF.', 2),
('d9811544-fe70-5a40-be35-bb88ab300483', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 16, 16, 'A capacitor network that is equivalent to 4.5 µF is placed across 10 V. How much charge, in µC, leaves the supply?', NULL, 1, 'numeric'::answer_type, '45 uC', 'µC', false, NULL, false, NULL, 'Q = CV = 4.5 × 10⁻⁶ × 10 = 4.5 × 10⁻⁵ C. In µC: 4.5 × 10⁻⁵ × 10⁶ = 45. Mark scheme (2 marks). C1: Q = C_total V. A1: Q = 45 µC.', 2),
('59e68dd7-b0ad-559a-9d1d-49bbf8c7783e', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 17, 17, 'Three identical capacitors, each of capacitance C, are connected with two in series and that pair in parallel with the third. What is the combined capacitance?', NULL, 1, 'multiple_choice'::answer_type, '1.5C', NULL, false, NULL, false, NULL, 'Series pair C/2, plus C in parallel: 1.5C. Mark scheme (1 mark). B1: B (1.5C).', 1),
('62cbe013-3fb1-5014-b708-b5f4a4b95023', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 18, 18, 'A 6.0 µF capacitor is in series with a parallel pair made of a 2.0 µF and a 4.0 µF capacitor. Calculate the combined capacitance, in µF.', NULL, 1, 'numeric'::answer_type, '3', 'µF', false, NULL, false, ARRAY['3e-6']::text[], 'Parallel pair: 2.0 + 4.0 = 6.0 µF. In series with 6.0 µF: C = 6.0 ÷ 2 = 3.0 µF. Mark scheme (2 marks). C1: parallel then series. A1: C = 3.0 µF.', 2),
('fe034bb2-771a-50ae-b346-9482fed25ba6', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 19, 19, 'In a network, two capacitors are connected between the same pair of junctions. What is the same for both?', NULL, 1, 'multiple_choice'::answer_type, 'The p.d. across them', NULL, false, NULL, false, NULL, 'Components between the same two junctions are in parallel. Mark scheme (1 mark). B1: C (The p.d. across them).', 1),
('bc0e26fb-ce57-5695-b32f-81df4ef9889c', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 20, 20, 'What is the equivalent capacitance, in µF, of a 100 µF capacitor in series with the parallel combination of 22 µF and 47 µF?', NULL, 1, 'numeric'::answer_type, '40.83', 'µF', false, NULL, false, ARRAY['4.083e-5']::text[], 'Parallel pair: 22 + 47 = 69 µF. In series with 100 µF: C = 69 × 100 ÷ 169 = 40.8 µF. Mark scheme (2 marks). C1: parallel then series. A1: C = 40.8 µF.', 2),
('93edd175-fb53-5eda-9bd5-9a69ef921199', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 21, 21, 'Four 8.0 µF capacitors are arranged as two series pairs, and the pairs are connected side by side. Find the total capacitance, in µF.', NULL, 1, 'numeric'::answer_type, '8', 'µF', false, NULL, false, ARRAY['8e-6']::text[], 'Each series pair is 4.0 µF; in parallel: 4.0 + 4.0 = 8.0 µF. Mark scheme (1 mark). A1: C = 8.0 µF.', 1),
('00ca7256-4a8c-566b-9b73-347f8237fd07', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 22, 22, 'What is (capacitance of three identical capacitors in parallel) ÷ (capacitance of the same three in series)?', NULL, 1, 'multiple_choice'::answer_type, '9', NULL, false, NULL, false, NULL, 'Parallel 3C; series C/3; ratio 9. Mark scheme (1 mark). B1: A (9).', 1),
('6402ee7d-db14-51b5-bbb9-9a0f65d41670', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 23, 23, 'A network that behaves as 2.0 µF is charged by a 50 V supply. What energy does it store, in mJ?', NULL, 1, 'numeric'::answer_type, '2.5 mJ', 'mJ', false, NULL, false, NULL, 'W = ½CV² = 0.5 × 2.0 × 10⁻⁶ × 50² = 2.5 × 10⁻³ J. In mJ: 2.5 × 10⁻³ × 1000 = 2.5. Mark scheme (2 marks). C1: W = ½CV². A1: W = 2.5 mJ.', 2),
('757e6f9c-3292-5f91-85a3-0922b5ec6998', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 24, 24, 'A 2.0 µF and a 4.0 µF capacitor in parallel are connected in series with a 3.0 µF capacitor across 12 V. Calculate the p.d. across the 3.0 µF capacitor.', NULL, 2, 'numeric'::answer_type, '8', 'V', false, NULL, false, NULL, 'Parallel pair 6.0 µF; total C = 6.0 × 3.0 ÷ 9.0 = 2.0 µF. Q = 2.0 × 10⁻⁶ × 12 = 2.4 × 10⁻⁵ C. V₃ = 2.4 × 10⁻⁵ ÷ 3.0 × 10⁻⁶ = 8.0 V. Mark scheme (3 marks). C1: total C. C1: Q = CV. C1: V = Q/C for the series capacitor.', 3),
('e9162a7c-e132-5d10-b0e5-7f1808a7d697', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 25, 25, 'In a network, a 2.0 µF and a 4.0 µF capacitor are in parallel, and the pair is in series with a 3.0 µF capacitor across 12 V. The p.d. across the 3.0 µF capacitor is 8.0 V. Calculate the charge on the 4.0 µF capacitor, in µC.', NULL, 2, 'numeric'::answer_type, '16 uC', 'µC', false, NULL, false, NULL, 'p.d. across the parallel pair: 12 − 8.0 = 4.0 V. Q = 4.0 × 10⁻⁶ × 4.0 = 1.6 × 10⁻⁵ C. In µC: 1.6 × 10⁻⁵ × 10⁶ = 16. Mark scheme (3 marks). C1: p.d.s add to 12 V. C1: Q = CV. A1: Q = 16 µC.', 3),
('503f1065-a052-5800-9821-47d4f69c11ef', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 26, 26, 'A branch of a 6.0 µF capacitor in series with a 3.0 µF capacitor is connected in parallel with a 4.0 µF capacitor, across a 9.0 V supply. Calculate the charge on the 3.0 µF capacitor, in µC.', NULL, 2, 'numeric'::answer_type, '18 uC', 'µC', false, NULL, false, NULL, 'Each branch has 9.0 V across it. Series branch: C = 6.0 × 3.0 ÷ 9.0 = 2.0 µF, so Q = 2.0 × 10⁻⁶ × 9.0 = 1.8 × 10⁻⁵ C on each of its capacitors. In µC: 1.8 × 10⁻⁵ × 10⁶ = 18. Mark scheme (4 marks). B1: each branch has the full 9.0 V. C1: series branch C. C1: Q = CV. A1: Q = 18 µC.', 4),
('93ebcffb-9322-5322-abf8-2f6421c20f0f', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 27, 27, 'Two capacitors are in series. A third capacitor is then connected in parallel with one of them. What happens to the combined capacitance?', NULL, 2, 'multiple_choice'::answer_type, 'It increases', NULL, false, NULL, false, NULL, 'The parallel pair has a larger capacitance, so the series combination increases. Mark scheme (3 marks). C1: parallel pair larger. C1: series total larger. A1: D (It increases).', 3),
('e033f687-e358-5b12-b18f-3a6a91006c2f', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 28, 28, 'An unknown capacitor X is in series with a 6.0 µF capacitor, and a 2.0 µF capacitor is connected in parallel with this series pair. The combined capacitance is 5.0 µF. Calculate X, in µF.', NULL, 2, 'numeric'::answer_type, '6', 'µF', false, NULL, false, ARRAY['6e-6']::text[], 'The series pair must be 5.0 − 2.0 = 3.0 µF. 1/X = 1/3.0 − 1/6.0, so X = 1 ÷ (1/3.0 − 1/6.0) = 6.0 µF. Mark scheme (3 marks). C1: series pair = 3.0 µF. C1: reciprocal rule rearranged. A1: X = 6.0 µF.', 3),
('b895705c-2edf-5449-8ba7-bbfc87542cfd', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 29, 29, 'A 3.0 µF capacitor is in series with a parallel pair of two 3.0 µF capacitors, across 12 V. Calculate the energy stored in the single 3.0 µF capacitor, in µJ.', NULL, 2, 'numeric'::answer_type, '96 uJ', 'µJ', false, NULL, false, NULL, 'Parallel pair 6.0 µF; total C = 3.0 × 6.0 ÷ 9.0 = 2.0 µF; Q = 2.0 × 10⁻⁶ × 12 = 2.4 × 10⁻⁵ C. W = Q²/2C = (2.4 × 10⁻⁵)² ÷ (2 × 3.0 × 10⁻⁶) = 9.6 × 10⁻⁵ J. In µJ: 9.6 × 10⁻⁵ × 10⁶ = 96. Mark scheme (4 marks). C1: total C. C1: same Q on series capacitor. C1: W = Q²/2C. A1: W = 96 µJ.', 4),
('a37f8d44-fb5f-5d3e-9a36-32496583999b', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 30, 30, 'A 2.0 µF capacitor is in series with a parallel pair made of a 6.0 µF and a 4.0 µF capacitor. Which capacitor has the largest p.d. across it when the network is connected to a supply?', NULL, 2, 'multiple_choice'::answer_type, 'The 2.0 µF capacitor', NULL, false, NULL, false, NULL, 'The parallel pair is 10 µF; in series, the smaller 2.0 µF takes five times the p.d. of the pair. Mark scheme (3 marks). C1: parallel pair 10 µF. C1: V ∝ 1/C in series. A1: B (The 2.0 µF capacitor).', 3),
('cd4008b5-fb65-5cef-9b51-61a1be924eb0', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 31, 31, 'Using a 1.0 µF, a 2.0 µF and a 3.0 µF capacitor, all three must be used. Calculate the smallest combined capacitance possible, in µF.', NULL, 2, 'numeric'::answer_type, '0.5455', 'µF', false, NULL, false, ARRAY['5.455e-7']::text[], 'All in series: C = 1 ÷ (1/1.0 + 1/2.0 + 1/3.0) = 0.545 µF. Mark scheme (3 marks). M1: all in series gives the smallest. C1: reciprocal sum. A1: C = 0.545 µF.', 3),
('35e8b4de-1407-5c2c-9dfc-f85004f588f1', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 32, 32, 'Two 10 µF capacitors in series are connected in parallel with another two 10 µF capacitors in series, and the network is connected across 20 V. Calculate the total energy stored, in mJ.', NULL, 2, 'numeric'::answer_type, '2 mJ', 'mJ', false, NULL, false, NULL, 'Each branch 5.0 µF; total 10 µF. W = 0.5 × 10 × 10⁻⁶ × 20² = 2.0 × 10⁻³ J. In mJ: 2.0 × 10⁻³ × 1000 = 2.0. Mark scheme (3 marks). C1: total C = 10 µF. C1: W = ½CV². A1: W = 2.0 mJ.', 3),
('2ebcbe51-f385-5a91-b0a3-022b2dad4148', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 33, 33, 'When are two capacitors in a network in series with each other?', NULL, 2, 'multiple_choice'::answer_type, 'When they are joined at a junction to which nothing else is connected, so the same charge must flow onto both', NULL, false, NULL, false, NULL, 'Series requires a single path: the joining node must have no other branch. Mark scheme (4 marks). C1: single junction with no other branch. C1: same charge. C1: drawing position irrelevant. A1: C (When they are joined at a junction to which nothing else is connected, so the same charge must flow onto both).', 4),
('e5b5a2ec-5eda-5fcc-8bb2-2f18702d1fa4', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 34, 34, 'Two 1.0 µF capacitors in series are connected in parallel with a 1.0 µF capacitor, and this combination is in series with a 1.5 µF capacitor. Calculate the combined capacitance, in µF.', NULL, 2, 'numeric'::answer_type, '0.75', 'µF', false, NULL, false, ARRAY['7.5e-7']::text[], 'Series pair 0.50 µF; parallel with 1.0 µF gives 1.5 µF; in series with 1.5 µF: 1.5 ÷ 2 = 0.75 µF. Mark scheme (3 marks). C1: inner reductions. C1: final series step. A1: C = 0.75 µF.', 3),
('38ad4d90-e392-57df-9a1b-f9372b1d5331', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 35, 35, 'A 4.0 µF capacitor C₁ is in series with a parallel pair C₂ = 2.0 µF and C₃ = 2.0 µF, across a 12 V supply. Calculate the charge on C₂, in µC.', NULL, 2, 'numeric'::answer_type, '12 uC', 'µC', false, NULL, false, NULL, 'Parallel pair 4.0 µF; total C = 2.0 µF; Q = 2.0 × 10⁻⁶ × 12 = 2.4 × 10⁻⁵ C. V₁ = 2.4 × 10⁻⁵ ÷ 4.0 × 10⁻⁶ = 6.0 V, so the pair has 6.0 V. Q₂ = 2.0 × 10⁻⁶ × 6.0 = 1.2 × 10⁻⁵ C. In µC: 1.2 × 10⁻⁵ × 10⁶ = 12. Mark scheme (4 marks). C1: total C. C1: p.d. across C₁. C1: p.d. across pair. C1: Q₂ = C₂V.', 4),
('3b4cbd57-5d69-5449-868d-691b83ae0fb8', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 36, 36, 'A network is connected across a fixed supply. A new capacitor is connected directly across the supply, in parallel with the whole network. What happens to the charges on the original capacitors?', NULL, 2, 'multiple_choice'::answer_type, 'They stay the same', NULL, false, NULL, false, NULL, 'The p.d. across the original network is still the supply p.d., so its charges are unchanged. Mark scheme (3 marks). C1: p.d. across network unchanged. C1: Q = CV unchanged. A1: A (They stay the same).', 3),
('5060c3d2-ec12-5c4e-8adc-03c14942e5df', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 37, 37, 'A 4.7 µF capacitor is connected in parallel with a branch of two 4.7 µF capacitors in series. Calculate the combined capacitance, in µF.', NULL, 2, 'numeric'::answer_type, '7.05', 'µF', false, NULL, false, ARRAY['7.05e-6']::text[], 'Series branch: 4.7 ÷ 2 = 2.35 µF. Total: 4.7 + 2.35 = 7.05 µF. Mark scheme (3 marks). C1: series branch. C1: add parallel. A1: C = 7.05 µF.', 3),
('03c4ff30-52f3-5aab-bb85-52ebfdbd59fe', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 38, 38, 'A 3.0 µF capacitor is in series with a parallel pair of a 6.0 µF and a 3.0 µF capacitor, across 24 V. Calculate the p.d. across the single 3.0 µF capacitor.', NULL, 2, 'numeric'::answer_type, '18', 'V', false, NULL, false, NULL, 'Parallel pair 9.0 µF; total C = 3.0 × 9.0 ÷ 12 = 2.25 µF; Q = 2.25 × 10⁻⁶ × 24 = 5.4 × 10⁻⁵ C. V = 5.4 × 10⁻⁵ ÷ 3.0 × 10⁻⁶ = 18 V. Mark scheme (3 marks). C1: total C. C1: Q = CV. C1: V = Q/C.', 3),
('22055414-78d8-552c-8d52-c47bba00e49b', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 39, 39, 'One capacitor in a series chain develops a short circuit. What happens to the combined capacitance of the chain?', NULL, 2, 'multiple_choice'::answer_type, 'It increases', NULL, false, NULL, false, NULL, 'Removing a term from the reciprocal sum makes 1/C smaller, so C rises. Mark scheme (3 marks). C1: fewer series capacitors. C1: total rises. A1: D (It increases).', 3),
('45acf745-704f-5751-9572-62e5e6641adf', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 40, 40, 'A 3.0 µF capacitor is in series with a parallel pair of a 6.0 µF and a 3.0 µF capacitor, across 24 V; the series 3.0 µF capacitor has 18 V across it. Calculate the energy stored in the 6.0 µF capacitor, in µJ.', NULL, 2, 'numeric'::answer_type, '108 uJ', 'µJ', false, NULL, false, NULL, 'p.d. across the parallel pair: 24 − 18 = 6.0 V. W = 0.5 × 6.0 × 10⁻⁶ × 6.0² = 1.08 × 10⁻⁴ J. In µJ: 1.08 × 10⁻⁴ × 10⁶ = 108. Mark scheme (4 marks). C1: p.d. across parallel pair. C1: W = ½CV². C1: conversion. A1: W = 108 µJ.', 4),
('79041e4e-f757-599a-994b-deddb9c105d7', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 41, 41, 'Three identical capacitors are connected with two in series and that pair in parallel with the third. The combined capacitance is 6.0 µF. Calculate the capacitance of each, in µF.', NULL, 2, 'numeric'::answer_type, '4', 'µF', false, NULL, false, ARRAY['4e-6']::text[], 'Combined = C/2 + C = 1.5C, so C = 6.0 ÷ 1.5 = 4.0 µF. Mark scheme (3 marks). C1: 1.5C. C1: rearranged. A1: C = 4.0 µF.', 3),
('971ea543-29d4-59d8-a0fb-b50f937ceaa1', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 42, 42, 'Four identical capacitors, each C, are to give a combined capacitance of C. Which arrangement does this?', NULL, 2, 'multiple_choice'::answer_type, 'Two series pairs connected in parallel', NULL, false, NULL, false, NULL, 'Each series pair is C/2; two in parallel give C. (Two parallel pairs in series also give C.). Mark scheme (3 marks). C1: series pair C/2. C1: two in parallel give C. A1: B (Two series pairs connected in parallel).', 3),
('e8f3b9d0-bab8-517a-9d73-630ce4361798', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 43, 43, 'A 5.0 µF capacitor is connected in parallel with a branch of two 10 µF capacitors in series, across 15 V. Calculate the charge on one of the 10 µF capacitors, in µC.', NULL, 2, 'numeric'::answer_type, '75 uC', 'µC', false, NULL, false, NULL, 'The series branch is 5.0 µF with 15 V across it: Q = 5.0 × 10⁻⁶ × 15 = 7.5 × 10⁻⁵ C on each capacitor in it. In µC: 7.5 × 10⁻⁵ × 10⁶ = 75. Mark scheme (3 marks). C1: branch C = 5.0 µF. C1: Q = CV for the branch. A1: Q = 75 µC.', 3),
('5e918ab8-b20a-517d-b94b-63691d57aa94', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 44, 44, 'In a network, C₁ = 2.0 µF and C₂ = 3.0 µF are in parallel; this pair is in series with C₃ = 10 µF; and the whole branch is in parallel with C₄ = 1.0 µF. The network is connected across 12 V. (a) Calculate the combined capacitance. (b) Calculate the total charge drawn from the supply. (c) Calculate the p.d. across C₃. (d) Calculate the charge on C₂, in µC. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '24 uC', 'µC', false, NULL, false, NULL, '(a) C₁ ∥ C₂ = 5.0 µF; with C₃ in series: 5.0 × 10 ÷ 15 = 3.33 µF; plus C₄: 4.33 µF. (b) Q = 4.333 × 12 = 52.0 µC. (c) The series branch has 12 V: Q_branch = 3.333 × 12 = 40 µC, so V₃ = 40 ÷ 10 = 4.0 V. (d) p.d. across the C₁ ∥ C₂ pair: 12 − 4.0 = 8.0 V. Q₂ = 3.0 × 8.0 = 24 µC. Mark scheme (6 marks). C1: inner parallel pair. C1: series with C₃. C1: total C. C1: V₃ from branch charge. C1: Q₂ = C₂V. A1: Q₂ = 24 µC.', 6),
('56b4f545-f8ad-5fcc-afd0-bfdb4741beeb', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 45, 45, 'A 12 µF capacitor is in series with a parallel pair of an 8.0 µF and a 4.0 µF capacitor, across 20 V. (a) Calculate the combined capacitance. (b) Calculate the charge drawn from the supply. (c) Calculate the p.d. across the parallel pair. (d) Calculate the energy stored in the 8.0 µF capacitor, in mJ. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '0.4 mJ', 'mJ', false, NULL, false, NULL, '(a) Parallel pair 12 µF; with 12 µF in series: C = 12 ÷ 2 = 6.0 µF. (b) Q = 6.0 × 10⁻⁶ × 20 = 1.2 × 10⁻⁴ C. (c) V = 1.2 × 10⁻⁴ ÷ 12 × 10⁻⁶ = 10 V. (d) W = 0.5 × 8.0 × 10⁻⁶ × 10² = 4.0 × 10⁻⁴ J. In mJ: 4.0 × 10⁻⁴ × 1000 = 0.40. Mark scheme (6 marks). C1: parallel pair. C1: series total. C1: Q = CV. C1: p.d. across pair. C1: W = ½CV². A1: W = 0.40 mJ.', 6),
('430a2382-527a-5ea7-83f9-379635650d1c', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 46, 46, 'Identical 10 µF capacitors rated at 25 V are available. A network is needed that has a combined capacitance of 10 µF and can safely be used at 50 V. (a) Explain why a single capacitor will not do. (b) Describe a suitable network and state how many capacitors it uses. (c) Calculate the energy stored by the network at 50 V, in mJ. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '12.5 mJ', 'mJ', false, NULL, false, NULL, '(a) A single capacitor would have 50 V across it, twice its rating. (b) Two series pairs connected in parallel: four capacitors; each pair shares 50 V as 25 V each, and gives 5.0 µF, so the two pairs give 10 µF. (c) W = 0.5 × 10 × 10⁻⁶ × 50² = 0.0125 J. In mJ: 0.0125 × 1000 = 12.5. Mark scheme (5 marks). B1: rating exceeded. B1: two series pairs in parallel. C1: four capacitors, 25 V each. C1: W = ½CV². A1: W = 12.5 mJ.', 5),
('ffdfffc6-e72d-5e5b-bd08-125b4c7e5083', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 47, 47, 'A 4.0 µF capacitor C₁ is charged to 12 V and disconnected. It is then connected across a series pair of uncharged capacitors, C₂ = 6.0 µF and C₃ = 3.0 µF. (a) Calculate the capacitance of the series pair. (b) Calculate the final p.d. across C₁. (c) Calculate the final p.d. across C₃. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '8', 'V', false, NULL, false, NULL, '(a) C = 6.0 × 3.0 ÷ 9.0 = 2.0 µF. (b) Charge 4.0 × 12 = 48 µC is shared between C₁ and the 2.0 µF pair in parallel: V = 48 ÷ (4.0 + 2.0) = 8.0 V. (c) The pair carries 2.0 × 8.0 = 16 µC, so V₃ = 16 ÷ 3.0 = 5.3 V. Mark scheme (6 marks). C1: series pair. M1: charge conserved. C1: shared over 6.0 µF. C1: charge on pair. C1: V₃. A1: V = 8.0 V.', 6),
('5a26f93e-4536-5148-9729-7232bbdadb09', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 48, 48, 'An unknown capacitor X is connected in series with a 4.7 µF capacitor, and a meter shows a combined capacitance of 3.1 µF. (a) Calculate X, in µF. (b) Capacitors have a tolerance of ±10 %. Explain how this affects your confidence in the value of X. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '9.106', 'µF', false, NULL, false, ARRAY['9.106e-6']::text[], '(a) 1/X = 1/3.1 − 1/4.7, so X = 1 ÷ (1/3.1 − 1/4.7) = 9.11 µF. (b) A small change in the 4.7 µF value makes a large change in the difference of reciprocals, so X is quite uncertain. Mark scheme (5 marks). M1: reciprocal rule rearranged. C1: substitution. C1: value. B1: uncertainty amplified by subtraction. A1: X = 9.11 µF.', 5),
('bd47d583-6475-5380-9f7c-9cc58ccccbed', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 49, 49, 'A 3.0 µF capacitor C₁ is in series with a parallel pair of a 2.0 µF capacitor C₂ and an unknown capacitor C₃. The network is connected to a 10 V supply, and the p.d. across C₁ is 6.0 V. (a) Calculate the charge on C₁. (b) Calculate the p.d. across the parallel pair. (c) Calculate C₃, in µF. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2.5', 'µF', false, NULL, false, ARRAY['2.5e-6']::text[], '(a) Q = 3.0 × 10⁻⁶ × 6.0 = 1.8 × 10⁻⁵ C. (b) 10 − 6.0 = 4.0 V. (c) The pair carries 1.8 × 10⁻⁵ C at 4.0 V, so C₂ + C₃ = 1.8 × 10⁻⁵ ÷ 4.0 = 4.5 × 10⁻⁶ F. C₃ = 4.5 − 2.0 = 2.5 µF. Mark scheme (6 marks). C1: Q = CV. C1: p.d.s add. M1: same charge on pair as on C₁. C1: pair capacitance. C1: subtract C₂. A1: C₃ = 2.5 µF.', 6),
('f5f62353-df52-5e76-b310-3057d07bb4e3', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 50, 50, 'In a network, C₁ = 6.0 µF is in series with C₂ = 3.0 µF; this pair is in parallel with C₃ = 4.0 µF; and the whole block is in series with C₄ = 12 µF. The network is connected to a 24 V supply. (a) Calculate the combined capacitance. (b) Calculate the charge drawn from the supply. (c) Calculate the p.d. across C₄ and across the block. (d) Calculate the p.d. across C₁. (e) Calculate the total energy stored. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '5.333', 'V', false, NULL, false, NULL, '(a) C₁, C₂ in series: 2.0 µF; with C₃: 6.0 µF; with C₄ in series: 6.0 × 12 ÷ 18 = 4.0 µF. (b) Q = 4.0 × 24 = 96 µC. (c) V₄ = 96 ÷ 12 = 8.0 V; block: 24 − 8.0 = 16 V. (d) The C₁–C₂ branch carries 2.0 × 16 = 32 µC, so V₁ = 32 ÷ 6.0 = 5.33 V. (e) W = 0.5 × 4.0 × 10⁻⁶ × 24² = 0.00115 J. Mark scheme (7 marks). C1: series pair. C1: block. C1: total C. C1: Q and V₄. M1: branch charge from block p.d. C1: total energy. A1: V₁ = 5.33 V.', 7)
