('d3ea9be5-6833-5cb1-890c-24c03dba3689', '59e68dd7-b0ad-559a-9d1d-49bbf8c7783e', '3C', 'A', false, 0),
('6f7ae3c9-3059-58a8-88bf-0825d573d61e', '59e68dd7-b0ad-559a-9d1d-49bbf8c7783e', '1.5C', 'B', true, 1),
('7cf71491-a600-5d01-a736-8d43aff45f97', '59e68dd7-b0ad-559a-9d1d-49bbf8c7783e', 'C/3', 'C', false, 2),
('3d24b965-8fa2-5c10-a49d-7f206952a5a3', '59e68dd7-b0ad-559a-9d1d-49bbf8c7783e', '2C/3', 'D', false, 3),
('d427758f-017b-51c8-8ab7-01ad362bfc2c', 'fe034bb2-771a-50ae-b346-9482fed25ba6', 'The charge on them', 'A', false, 0),
