('3031e22e-4b1a-5b2b-8fbd-7bdcd11c278f', 'fe034bb2-771a-50ae-b346-9482fed25ba6', 'The p.d. across them', 'C', true, 2),
('91737986-a690-5e99-9bef-ca84b9b19f39', 'fe034bb2-771a-50ae-b346-9482fed25ba6', 'Their capacitance', 'D', false, 3),
('2b46120c-aa78-5880-b5d6-5edabb7d859f', '00ca7256-4a8c-566b-9b73-347f8237fd07', '9', 'A', true, 0),
('1fcec670-4488-5030-9ea6-c465f15b140a', '00ca7256-4a8c-566b-9b73-347f8237fd07', '3', 'B', false, 1),
('4e86d370-fca5-535d-8211-a65f4dd411be', '00ca7256-4a8c-566b-9b73-347f8237fd07', '1', 'C', false, 2),
