('a2943051-a016-50d7-941d-bb6d8fdbb9d4', '93ebcffb-9322-5322-abf8-2f6421c20f0f', 'It decreases', 'A', false, 0),
('5ed1c382-8c76-55b9-9e30-70f06b2e5355', '93ebcffb-9322-5322-abf8-2f6421c20f0f', 'It stays the same', 'B', false, 1),
('a72242a7-0fdc-5714-b7e0-8e0de64a7175', '93ebcffb-9322-5322-abf8-2f6421c20f0f', 'It becomes zero', 'C', false, 2),
('04ad51a0-acd2-5fe5-9947-ab83f87c6bba', '93ebcffb-9322-5322-abf8-2f6421c20f0f', 'It increases', 'D', true, 3),
('f99c2510-4e2f-5f89-b22e-e43d7101d764', 'a37f8d44-fb5f-5d3e-9a36-32496583999b', 'The 6.0 µF capacitor', 'A', false, 0),
('ac18e2a3-3e83-5ce1-badb-0449f6b30b43', 'a37f8d44-fb5f-5d3e-9a36-32496583999b', 'The 2.0 µF capacitor', 'B', true, 1),
('63c9ed3e-5ab7-51d9-9204-50386d79d5cb', 'a37f8d44-fb5f-5d3e-9a36-32496583999b', 'The 4.0 µF capacitor', 'C', false, 2),
('8d81e1c3-4f57-5a04-b31f-7890c151c70f', 'a37f8d44-fb5f-5d3e-9a36-32496583999b', 'All have the same p.d.', 'D', false, 3),
('b2468099-3050-5136-bbfe-60521ecda68a', '2ebcbe51-f385-5a91-b0a3-022b2dad4148', 'Whenever they are drawn one after the other on the diagram', 'A', false, 0),
('08187aac-8efd-592b-a393-35c242db2e3b', '2ebcbe51-f385-5a91-b0a3-022b2dad4148', 'Whenever they have the same capacitance', 'B', false, 1),
('ced1959f-9818-5aee-8933-98e9f6aa0dbb', '2ebcbe51-f385-5a91-b0a3-022b2dad4148', 'When they are joined at a junction to which nothing else is connected, so the same charge must flow onto both', 'C', true, 2),
('bf4682be-ef8e-58ff-9c4a-b8f2e2e77dec', '2ebcbe51-f385-5a91-b0a3-022b2dad4148', 'Whenever they are connected to the same supply', 'D', false, 3),
('47bcfc40-4d04-53cd-b202-a1c49659bf62', '3b4cbd57-5d69-5449-868d-691b83ae0fb8', 'They stay the same', 'A', true, 0),
('e5a883cc-42fc-5a46-b7fb-a0b584d3796f', '3b4cbd57-5d69-5449-868d-691b83ae0fb8', 'They all increase', 'B', false, 1),
('cdcc578c-8d08-5cea-a36e-b419ce4d7ee4', '3b4cbd57-5d69-5449-868d-691b83ae0fb8', 'They all decrease', 'C', false, 2),
('dd01fc00-c203-56d1-8cb4-6a6ae351fc01', '3b4cbd57-5d69-5449-868d-691b83ae0fb8', 'They become zero', 'D', false, 3),
('26f4b067-a287-5aae-be35-c4135f0baa9d', '22055414-78d8-552c-8d52-c47bba00e49b', 'It decreases', 'A', false, 0),
('4955f853-17de-571f-beb8-7430ba78c658', '22055414-78d8-552c-8d52-c47bba00e49b', 'It stays the same', 'B', false, 1),
('2ba31437-3f17-57ed-9779-15453345c93c', '22055414-78d8-552c-8d52-c47bba00e49b', 'It becomes zero', 'C', false, 2),
('47c7978a-31b3-5562-a870-3180d8e56594', '22055414-78d8-552c-8d52-c47bba00e49b', 'It increases', 'D', true, 3),
('6ff3fa80-4dcc-5125-8308-058e74712ccd', '971ea543-29d4-59d8-a0fb-b50f937ceaa1', 'All four in parallel', 'A', false, 0),
('b94d0843-8c82-5f50-82a2-9e32ac144e22', '971ea543-29d4-59d8-a0fb-b50f937ceaa1', 'Two series pairs connected in parallel', 'B', true, 1),
('cfa5ebcd-2d3f-53a2-b101-446f2e8d1045', '971ea543-29d4-59d8-a0fb-b50f937ceaa1', 'All four in series', 'C', false, 2),
('b052f64f-ebfe-5f37-becb-73445c75442e', '971ea543-29d4-59d8-a0fb-b50f937ceaa1', 'Three in parallel, in series with the fourth', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('96e990fc-60b8-585e-9f4f-8280e5a7c51b', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 6, 6, 'A charged capacitor discharges through a resistor. Which describes the graph of current against time?', NULL, 1, 'multiple_choice'::answer_type, 'An exponential decay curve', NULL, false, NULL, false, NULL, 'I = I₀e^(−t/RC): the current falls by the same fraction in each equal time interval. Mark scheme (1 mark). B1: C (An exponential decay curve).', 1),
('448a39ac-197b-5a27-b291-70601f552069', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 7, 7, 'A 2200 µF capacitor discharges through a 1.0 kΩ resistor. Calculate the time constant.', NULL, 1, 'numeric'::answer_type, '2.2', 's', false, NULL, false, NULL, 'τ = RC = 1000 × 2200 × 10⁻⁶ = 2.2 s. Mark scheme (2 marks). C1: τ = RC. A1: τ = 2.2 s.', 2),
('55e5e9e0-7c6b-5852-b12f-c82be5a2ce4d', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 8, 8, 'What is the time constant of a discharging capacitor circuit?', NULL, 1, 'multiple_choice'::answer_type, 'The time for the charge to fall to 1/e (about 37 %) of its initial value', NULL, false, NULL, false, NULL, 'At t = RC, Q = Q₀e⁻¹ ≈ 0.37Q₀. Mark scheme (1 mark). B1: A (The time for the charge to fall to 1/e (about 37 %) of its initial value).', 1),
('6000d6d0-f400-562b-bf36-b2411354e536', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 9, 9, 'What fraction of its initial charge remains on a discharging capacitor after two time constants?', NULL, 1, 'numeric'::answer_type, '0.1353', NULL, false, NULL, false, NULL, 'Q/Q₀ = e^(−2) = 0.135. Mark scheme (2 marks). C1: Q/Q₀ = e^(−t/RC). A1: fraction = 0.135.', 2),
('4666562e-5ca0-5e8e-bcdc-8390eeaffb5a', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 10, 10, 'The instant a capacitor charged to 6.0 V begins discharging through a 1.5 kΩ resistor, what current flows, in mA?', NULL, 1, 'numeric'::answer_type, '4 mA', 'mA', false, NULL, false, NULL, 'I₀ = V₀/R = 6.0 ÷ 1500 = 4.0 × 10⁻³ A. In mA: 4.0 × 10⁻³ × 1000 = 4.0. Mark scheme (2 marks). C1: I₀ = V₀/R. A1: I₀ = 4.0 mA.', 2),
('9582fc07-8f53-5456-8993-427088d63c0e', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 11, 11, 'The resistance through which a capacitor discharges is increased. What happens?', NULL, 1, 'multiple_choice'::answer_type, 'The capacitor discharges more slowly', NULL, false, NULL, false, NULL, 'τ = RC increases, so the decay is slower. Mark scheme (1 mark). B1: D (The capacitor discharges more slowly).', 1),
('85fae43e-ef5d-5fcd-a3b1-2a01d1cc88e0', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 12, 12, 'A capacitor initially holds 4.0 mC. Calculate the charge remaining after one time constant, in mC.', NULL, 1, 'numeric'::answer_type, '1.472 mC', 'mC', false, NULL, false, NULL, 'Q = Q₀e^(−1) = 4.0 × e^(−1) = 1.47 mC. Mark scheme (2 marks). C1: Q = Q₀e⁻¹. A1: Q = 1.47 mC.', 2),
('1fb4f9e3-b3f5-5e2e-a17c-8b3c7d43091c', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 13, 13, 'What is the unit of the product RC?', NULL, 1, 'multiple_choice'::answer_type, 's', NULL, false, NULL, false, NULL, 'Ω × F = (V A⁻¹)(C V⁻¹) = C A⁻¹ = s. Mark scheme (1 mark). B1: B (s).', 1),
('7c09f2d6-c225-5157-9408-86c9413125a3', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 14, 14, 'A 47 µF capacitor in a sensor circuit drains through a 220 kΩ resistor. What is RC for this circuit?', NULL, 1, 'numeric'::answer_type, '10.34', 's', false, NULL, false, NULL, 'τ = RC = 220 × 10³ × 47 × 10⁻⁶ = 10.3 s. Mark scheme (2 marks). C1: τ = RC with prefixes converted. A1: τ = 10.3 s.', 2),
('e50ce724-5e25-5b03-8c52-7f3d89614e7b', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 15, 15, 'For a discharging capacitor, what does a graph of ln(V) against t look like?', NULL, 1, 'multiple_choice'::answer_type, 'A straight line with gradient −1/RC', NULL, false, NULL, false, NULL, 'V = V₀e^(−t/RC) gives ln V = ln V₀ − t/RC. Mark scheme (1 mark). B1: C (A straight line with gradient −1/RC).', 1),
('26369a4d-3f5f-5284-82cf-592683d1a7d2', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 16, 16, 'A discharge circuit has a time constant of 5.0 s. Calculate the time for the charge to halve.', NULL, 1, 'numeric'::answer_type, '3.466', 's', false, NULL, false, NULL, 't½ = RC ln 2 = 5.0 × ln 2 = 3.47 s. Mark scheme (2 marks). C1: t½ = RC ln 2. A1: t½ = 3.47 s.', 2),
('a360e909-dabf-57fc-9abd-e95fbe4cc8a3', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 17, 17, 'In each 2.0 s interval, a discharging capacitor loses 30 % of the charge it had at the start of that interval. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'The discharge is exponential', NULL, false, NULL, false, NULL, 'Losing a constant fraction in equal time intervals is the property of exponential decay. Mark scheme (1 mark). B1: A (The discharge is exponential).', 1),
('98689426-aa36-5e02-b0b3-ee5fa2bb69f1', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 18, 18, 'Engineers often treat a capacitor as fully discharged after 5RC. What fraction of its charge is actually left then?', NULL, 1, 'numeric'::answer_type, '0.006738', NULL, false, NULL, false, NULL, 'Q/Q₀ = e^(−5) = 0.00674. Mark scheme (1 mark). A1: fraction = 0.00674.', 1),
('06a7d94b-57dd-5026-8d4d-a00cb2fcde3f', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 19, 19, 'During the discharge of a capacitor through a resistor, how do the current and the p.d. across the capacitor change?', NULL, 1, 'multiple_choice'::answer_type, 'Both decay exponentially with the same time constant', NULL, false, NULL, false, NULL, 'I = V/R at every instant, so both follow e^(−t/RC). Mark scheme (1 mark). B1: D (Both decay exponentially with the same time constant).', 1),
('f16f53e8-1573-5960-9b34-31c9dbcc8640', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 20, 20, 'A 470 µF capacitor charged to 9.0 V discharges through a 10 kΩ resistor. Calculate the p.d. across it after 3.0 s.', NULL, 2, 'numeric'::answer_type, '4.754', 'V', false, NULL, false, NULL, 'RC = 10 × 10³ × 470 × 10⁻⁶ = 4.7 s. V = 9.0 × e^(−3.0/4.7) = 4.75 V. Mark scheme (3 marks). C1: RC. C1: V = V₀e^(−t/RC). A1: V = 4.75 V.', 3),
('30fe5421-a0c7-50a3-bb22-33fb469788cf', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 21, 21, 'A capacitor discharges from 12 V through a resistor with a time constant of 2.2 s. Calculate the time for the p.d. to fall to 2.0 V.', NULL, 2, 'numeric'::answer_type, '3.942', 's', false, NULL, false, NULL, 'V/V₀ = e^(−t/RC) gives t = RC ln(V₀/V) = 2.2 × ln 6 = 3.94 s. Mark scheme (3 marks). C1: take natural logs. C1: t = RC ln(V₀/V). A1: t = 3.94 s.', 3),
('ab8b54c0-d109-54a3-a2fb-141efb7289a0', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 22, 22, 'A 100 µF capacitor discharges through a resistor. Its p.d. falls from 10 V to 5.0 V in 6.9 s. Calculate the resistance, in kΩ.', NULL, 2, 'numeric'::answer_type, '99.55', 'kΩ', false, NULL, false, ARRAY['99546']::text[], 'Half-life: t½ = RC ln 2, so RC = 6.9 ÷ ln 2 = 9.95 s. R = 9.955 ÷ 100 × 10⁻⁶ = 9.95 × 10⁴ Ω. In kΩ: 9.955 × 10⁴ ÷ 1000 = 99.5. Mark scheme (4 marks). M1: t½ = RC ln 2. C1: RC. C1: R = RC/C. A1: R = 99.5 kΩ.', 4),
('7d5c4d9f-a93a-5b04-a5f8-6513fdb1ab8e', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 23, 23, 'The capacitance in a discharge circuit is doubled and the resistance is halved. What happens to the time constant?', NULL, 2, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'τ = RC, and doubling C while halving R leaves the product unchanged. Mark scheme (3 marks). C1: τ = RC. C1: product unchanged. A1: B (It stays the same).', 3),
('a20ac572-5c0b-57cc-bb3e-79e6f8580920', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 24, 24, 'The initial discharge current of a capacitor is 2.0 mA and the time constant is 4.0 s. Calculate the current after 5.0 s, in mA.', NULL, 2, 'numeric'::answer_type, '0.573 mA', 'mA', false, NULL, false, NULL, 'I = I₀e^(−t/RC) = 2.0 × e^(−5.0/4.0) = 0.573 mA. Mark scheme (3 marks). C1: I = I₀e^(−t/RC). C1: substitution. A1: I = 0.573 mA.', 3),
('d27245f7-cf6d-5d23-92fb-a3b94371b281', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 25, 25, 'A 220 µF capacitor discharges through a 47 kΩ resistor. Calculate the percentage of the initial charge remaining after 10 s.', NULL, 2, 'numeric'::answer_type, '38.02', '%', false, NULL, false, NULL, 'RC = 47 × 10³ × 220 × 10⁻⁶ = 10.3 s. Q/Q₀ = e^(−10/10.34) = 0.3802. Percentage: 0.3802 × 100 = 38.0 %. Mark scheme (3 marks). C1: RC. C1: e^(−t/RC). A1: percentage = 38.0%.', 3),
('c9c6827e-5c05-5dab-b8c5-00e0d72f2314', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 26, 26, 'What fraction of the initial stored energy remains in a discharging capacitor after one time constant?', NULL, 2, 'multiple_choice'::answer_type, 'About 0.14', NULL, false, NULL, false, NULL, 'W ∝ V², so W/W₀ = (e⁻¹)² = e⁻² ≈ 0.135. 0.37 is the charge fraction. Mark scheme (3 marks). C1: W ∝ V². C1: e⁻². A1: C (About 0.14).', 3),
('a75f4f78-4d69-5c99-b895-9d5785e13dc2', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 27, 27, 'A capacitor discharges with a time constant of 3.0 s. Calculate the time taken for its stored energy to halve.', NULL, 2, 'numeric'::answer_type, '1.04', 's', false, NULL, false, NULL, 'W ∝ V² ∝ e^(−2t/RC). Setting e^(−2t/RC) = ½ gives t = RC ln 2 ÷ 2 = 3.0 × ln 2 ÷ 2 = 1.04 s. Mark scheme (4 marks). M1: W ∝ e^(−2t/RC). C1: logs. C1: substitution. A1: t = 1.04 s.', 4),
('1c333440-daa2-5f24-91f9-02238cb81a37', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 28, 28, 'A graph of ln(V/V) against t for a discharging capacitor has a gradient of −0.25 s⁻¹. The resistor is 20 kΩ. Calculate the capacitance, in µF.', NULL, 2, 'numeric'::answer_type, '200', 'µF', false, NULL, false, ARRAY['2e-4']::text[], 'Gradient = −1/RC, so RC = 1 ÷ 0.25 = 4.0 s. C = 4.0 ÷ 20 × 10³ = 2.0 × 10⁻⁴ F. In µF: 2.0 × 10⁻⁴ × 10⁶ = 200. Mark scheme (3 marks). M1: gradient = −1/RC. C1: C = RC/R. A1: C = 200 µF.', 3),
('5eaf572a-5bdd-5a8f-b58c-e4ebf2ebe1e2', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 29, 29, 'Why does the discharge current of a capacitor decrease with time?', NULL, 2, 'multiple_choice'::answer_type, 'As the charge falls, the p.d. across the capacitor falls, so the current V/R falls', NULL, false, NULL, false, NULL, 'I = V/R and V = Q/C, so the rate of loss of charge is proportional to the charge left. Mark scheme (3 marks). C1: V falls with Q. C1: I = V/R. A1: A (As the charge falls, the p.d. across the capacitor falls, so the current V/R falls).', 3),
('1f81405b-b3f4-51cf-b9a5-7ed496d04f72', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 30, 30, 'A capacitor initially holds 6.0 mC and discharges through a circuit with RC = 3.0 s. Calculate the initial discharge current, in mA.', NULL, 2, 'numeric'::answer_type, '2 mA', 'mA', false, NULL, false, NULL, 'I₀ = Q₀/RC = 6.0 × 10⁻³ ÷ 3.0 = 2.0 × 10⁻³ A. In mA: 2.0 × 10⁻³ × 1000 = 2.0. Mark scheme (3 marks). C1: I₀ = V₀/R = Q₀/RC. C1: conversion. A1: I₀ = 2.0 mA.', 3),
('ea70fa51-fa73-53f4-8b3f-995cfdde2b19', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 31, 31, 'How many time constants does it take for the p.d. across a discharging capacitor to fall to 1.0 % of its initial value?', NULL, 2, 'numeric'::answer_type, '4.605', NULL, false, NULL, false, NULL, '0.010 = e^(−t/RC), so t/RC = ln 100 = 4.61. Mark scheme (4 marks). C1: V/V₀ = 0.010. M1: natural logs. C1: value. A1: t/RC = 4.61.', 4),
('56840262-aa52-551b-874e-a08ceb4a2696', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 32, 32, 'Two identical capacitors discharge through identical resistors, one starting from 12 V and the other from 6.0 V. How do the times for their p.d.s to halve compare?', NULL, 2, 'multiple_choice'::answer_type, 'They are the same', NULL, false, NULL, false, NULL, 'The half-life RC ln 2 does not depend on the starting value. Mark scheme (3 marks). C1: t½ = RC ln 2. C1: independent of V₀. A1: D (They are the same).', 3),
('df897a0d-0225-5573-91c2-3db9f77caa24', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 33, 33, 'A 0.22 F memory-backup capacitor discharges through a 47 kΩ load. Calculate the time constant, in hours.', NULL, 2, 'numeric'::answer_type, '2.872', 'hours', false, NULL, false, NULL, 'RC = 47 × 10³ × 0.22 = 1.03 × 10⁴ s. In hours: 1.034 × 10⁴ ÷ 3600 = 2.87. Mark scheme (3 marks). C1: RC. C1: seconds to hours. A1: τ = 2.87 hours.', 3),
('09270358-f8f9-5eac-8125-fbf336d10aac', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 34, 34, 'In a camera sensor, a 100 nF capacitor at 5.0 V is drained through 10 kΩ. What is its p.d. 2.0 ms later?', NULL, 2, 'numeric'::answer_type, '0.6767', 'V', false, NULL, false, NULL, 'RC = 10 × 10³ × 100 × 10⁻⁹ = 1.0 × 10⁻³ s. V = 5.0 × e^(−2.0) = 0.677 V. Mark scheme (3 marks). C1: RC. C1: V = V₀e^(−t/RC). A1: V = 0.677 V.', 3),
('f847c43c-9e07-5b3c-8988-742fe335a734', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 35, 35, 'How is the half-life t½ of a capacitor discharge related to the time constant RC?', NULL, 2, 'multiple_choice'::answer_type, 't½ = RC ln 2 ≈ 0.69RC', NULL, false, NULL, false, NULL, 'Setting Q = Q₀/2 in Q = Q₀e^(−t/RC) gives t = RC ln 2. Mark scheme (4 marks). C1: Q = Q₀/2. C1: logs. C1: ln 2 ≈ 0.69. A1: B (t½ = RC ln 2 ≈ 0.69RC).', 4),
('4774cc73-9b6e-5386-97fe-14669654b3a4', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 36, 36, 'A capacitor initially holding 5.0 mC discharges through a resistor. Calculate the charge that flows through the resistor during the first time constant, in mC.', NULL, 2, 'numeric'::answer_type, '3.161 mC', 'mC', false, NULL, false, NULL, 'Remaining: 5.0e⁻¹; flowed = 5.0 × (1 − e^(−1)) = 3.16 mC. Mark scheme (3 marks). C1: Q = Q₀e⁻¹ remaining. C1: difference. A1: ΔQ = 3.16 mC.', 3),
('2ce967f4-a659-5b9b-b39e-8a6b9290240b', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 37, 37, 'A 1000 µF capacitor charged to 20 V discharges completely through a resistor. Calculate the total energy dissipated in the resistor.', NULL, 2, 'numeric'::answer_type, '0.2', 'J', false, NULL, false, NULL, 'All the stored energy is converted to heat: W = 0.5 × 1000 × 10⁻⁶ × 20² = 0.20 J. Mark scheme (4 marks). B1: all stored energy dissipated. C1: W = ½CV². C1: substitution. A1: W = 0.20 J.', 4),
('44718347-9cb9-599a-8713-ef1424fc82db', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 38, 38, 'A high-resistance digital voltmeter (10 MΩ) is connected across a charged 1.0 µF capacitor. Why does its reading slowly fall?', NULL, 2, 'multiple_choice'::answer_type, 'The capacitor discharges through the voltmeter with a time constant of about 10 s', NULL, false, NULL, false, NULL, 'RC = 10 × 10⁶ × 1.0 × 10⁻⁶ = 10 s, so the reading decays noticeably within seconds. Mark scheme (3 marks). C1: meter provides discharge path. C1: RC ≈ 10 s. A1: C (The capacitor discharges through the voltmeter with a time constant of about 10 s).', 3),
('5b89e8f5-0e87-5499-b36c-589964c081f1', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 39, 39, 'A capacitor discharges through a 100 kΩ resistor. The p.d. is recorded: t/s = 0, 10, 20, 30, 40 and V/V = 12.0, 7.3, 4.4, 2.7, 1.6. (a) Explain why a graph of ln(V/V) against t should be a straight line. (b) Calculate the gradient using the first and last readings. (c) Calculate the time constant. (d) Calculate the capacitance, in µF. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '198.5', 'µF', false, NULL, false, ARRAY['1.985e-4']::text[], '(a) V = V₀e^(−t/RC), so ln V = ln V₀ − t/RC: linear in t. (b) Gradient = (ln 1.6 − ln 12.0) ÷ 40 = −0.0504 s⁻¹. (c) RC = −1 ÷ gradient = 40 ÷ (ln 12.0 − ln 1.6) = 19.9 s. (d) C = 19.85 ÷ 100 × 10³ = 1.99 × 10⁻⁴ F. In µF: 1.985 × 10⁻⁴ × 10⁶ = 199. Mark scheme (6 marks). B1: ln V linear in t. C1: gradient. M1: gradient = −1/RC. C1: RC. C1: C = RC/R. A1: C = 199 µF.', 6),
('6d425200-989b-5771-81cb-75417975c790', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 40, 40, 'The p.d. across a 470 µF capacitor discharging through a resistor halves every 3.5 s. (a) Show that the half-life is RC ln 2. (b) Calculate the time constant. (c) Calculate the resistance, in kΩ. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '10.74', 'kΩ', false, NULL, false, ARRAY['10743']::text[], '(a) V₀/2 = V₀e^(−t/RC) gives t = RC ln 2. (b) RC = 3.5 ÷ ln 2 = 5.05 s. (c) R = 5.049 ÷ 470 × 10⁻⁶ = 1.07 × 10⁴ Ω. In kΩ: 1.074 × 10⁴ ÷ 1000 = 10.7. Mark scheme (5 marks). M1: half-life from exponential. C1: RC = t½/ln 2. C1: R = RC/C. C1: conversion to kΩ. A1: R = 10.7 kΩ.', 5),
('b2a2af9d-e39b-5e9c-82b0-9107d4f65235', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 41, 41, 'A defibrillator capacitor of 32 µF is charged to 5.0 kV and discharges through a patient''s chest, of resistance 50 Ω. (a) Calculate the time constant, in ms. (b) Calculate the initial current. (c) Calculate the energy delivered to the patient in the first 2.0 ms. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '367.2', 'J', false, NULL, false, NULL, '(a) RC = 50 × 32 × 10⁻⁶ = 1.6 × 10⁻³ s, which is 1.6 ms. (b) I₀ = 5.0 × 10³ ÷ 50 = 100 A. (c) W₀ = 0.5 × 32 × 10⁻⁶ × (5.0 × 10³)² = 400 J. W ∝ V², so the energy left is W₀e^(−2t/RC) and the energy delivered = 400 × (1 − e^(−2 × 2.0/1.6)) = 367 J. Mark scheme (6 marks). C1: RC. C1: I₀ = V₀/R. C1: W₀ = ½CV². M1: W ∝ e^(−2t/RC). C1: energy delivered. A1: W = 367 J.', 6),
('f4fcb6e1-2721-57d8-bf68-043330d409b4', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 42, 42, '(a) Starting from Q = Q₀e^(−t/RC), show that ln Q = ln Q₀ − t/RC. (b) A 220 µF capacitor discharges through a 15 kΩ resistor. Calculate the time taken for it to lose 75 % of its charge. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '4.575', 's', false, NULL, false, NULL, '(a) Taking natural logs: ln Q = ln Q₀ + ln e^(−t/RC) = ln Q₀ − t/RC. (b) RC = 15 × 10³ × 220 × 10⁻⁶ = 3.3 s. 25 % remains: 0.25 = e^(−t/RC), so t = 3.3 × ln 4 = 4.57 s. Mark scheme (5 marks). B1: logs taken correctly. C1: RC. M1: 25 % remains. C1: t = RC ln 4. A1: t = 4.57 s.', 5),
('bd02f10c-0458-5141-a5de-67b5c21f491f', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 43, 43, 'A timer circuit switches a light off when the p.d. across a discharging 1000 µF capacitor falls from 9.0 V to 3.0 V. The delay must be 60 s. (a) Show that the delay is RC ln 3. (b) Calculate the resistance needed, in kΩ. (c) Suggest why the actual delay might differ from 60 s. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '54.61', 'kΩ', false, NULL, false, ARRAY['54614']::text[], '(a) V/V₀ = e^(−t/RC) with V₀/V = 3, so t = RC ln 3. (b) RC = 60 ÷ ln 3 = 54.6 s. R = 54.61 ÷ 1000 × 10⁻⁶ = 5.46 × 10⁴ Ω. In kΩ: 5.461 × 10⁴ ÷ 1000 = 54.6. (c) Capacitors have a wide tolerance (often ±20 %) and can leak, and the switching p.d. may vary. Mark scheme (5 marks). M1: V/V₀ = 1/3. C1: RC. C1: R in kΩ. B1: tolerance or leakage. A1: R = 54.6 kΩ.', 5),
('64f762d7-f1be-5d9e-bda0-63e70effbe8a', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 44, 44, 'A 100 µF capacitor charged to 10 V discharges through a 20 kΩ resistor for 2.0 s. The resistor is then switched to 5.0 kΩ and the discharge continues. (a) Calculate the p.d. after the first 2.0 s. (b) Calculate the new time constant. (c) Calculate the p.d. 1.0 s after the switch. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.4979', 'V', false, NULL, false, NULL, '(a) RC₁ = 20 × 10³ × 100 × 10⁻⁶ = 2.0 s; V = 10 × e^(−1) = 3.68 V. (b) RC₂ = 5.0 × 10³ × 100 × 10⁻⁶ = 0.50 s. (c) V = 3.679 × e^(−1.0/0.50) = 0.498 V. Mark scheme (6 marks). C1: first RC. C1: V after 2.0 s. C1: second RC. M1: new decay starts from the p.d. at the switch. C1: final V. A1: V = 0.498 V.', 6),
('a55f618f-03a7-5244-a44c-f0d7053349e9', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 45, 45, 'Because its dielectric is not a perfect insulator, an isolated 4.7 µF capacitor loses half its p.d. in 2.0 hours. (a) Calculate the time constant. (b) Calculate the leakage resistance, in GΩ. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2.21', 'GΩ', false, NULL, false, ARRAY['2.21e9']::text[], '(a) RC = t½ ÷ ln 2 = 7200 ÷ ln 2 = 1.04 × 10⁴ s. (b) R = 1.039 × 10⁴ ÷ 4.7 × 10⁻⁶ = 2.21 × 10⁹ Ω. In GΩ: 2.210 × 10⁹ ÷ 10⁹ = 2.21. Mark scheme (5 marks). C1: hours to seconds. M1: RC = t½/ln 2. C1: R = RC/C. C1: conversion to GΩ. A1: R = 2.21 GΩ.', 5),
('3ac007c7-4cab-5c94-9513-6746888d6de8', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 46, 46, 'A capacitor initially charged to 9.0 V discharges through a resistor. The current is 0.50 mA at the start and 0.18 mA after 20 s. (a) Calculate the time constant. (b) Calculate the initial charge, using Q₀ = I₀RC. (c) Calculate the capacitance, in µF. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1088', 'µF', false, NULL, false, ARRAY['0.001088']::text[], '(a) I = I₀e^(−t/RC), so RC = t ÷ ln(I₀/I) = 20 ÷ ln(0.50/0.18) = 19.6 s. (b) Q₀ = 0.50 × 10⁻³ × 19.58 = 0.00979 C. (c) C = Q₀/V₀ = 0.009788 ÷ 9.0 = 0.00109 F. In µF: 0.001088 × 10⁶ = 1090. Mark scheme (6 marks). C1: logs of current ratio. C1: RC. M1: Q₀ = I₀RC. C1: C = Q₀/V₀. C1: conversion to µF. A1: C = 1090 µF.', 6),
('1afeed5a-9835-5832-ab4e-95a291509b3e', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 47, 47, 'A 470 µF capacitor charged to 12 V discharges through a 1.0 kΩ resistor. (a) Calculate the initial power dissipated in the resistor. (b) Show that the power falls as e^(−2t/RC). (c) Calculate the power after one time constant, in mW. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '19.49 mW', 'mW', false, NULL, false, NULL, '(a) P₀ = V₀²/R = 12² ÷ 1000 = 0.144 W. (b) P = V²/R and V ∝ e^(−t/RC), so P ∝ e^(−2t/RC). (c) P = 0.144 × e^(−2) = 0.0195 W. In mW: 0.01949 × 1000 = 19.5. Mark scheme (5 marks). C1: P = V²/R. B1: P ∝ e^(−2t/RC). C1: e⁻² factor. C1: conversion to mW. A1: P = 19.5 mW.', 5),
('166a13bd-6dc3-5aaf-afc0-02d2d4c6bb18', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 48, 48, '(a) Show that the product RC has the unit of seconds. (b) A discharging capacitor has RC = 2.0 s. Calculate the time taken for its p.d. to fall by 20 %. (c) Calculate the fraction of the initial energy remaining at that time. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.4463', 's', false, NULL, false, NULL, '(a) Ω × F = (V A⁻¹)(C V⁻¹) = C A⁻¹ = (A s) A⁻¹ = s. (b) V = 0.80V₀, so t = RC ln(1/0.80) = 2.0 × ln 1.25 = 0.446 s. (c) W ∝ V², so the fraction = 0.80² = 0.64. Mark scheme (5 marks). B1: units shown. M1: V/V₀ = 0.80. C1: t = RC ln(1/0.80). C1: energy fraction 0.64. A1: t = 0.446 s.', 5),
('b1d27b6f-44e1-5c8d-8a55-388dd9a70769', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 49, 49, 'A student measures the time t½ for the p.d. across a capacitor to fall from 10 V to 5.0 V using different resistors: R/kΩ = 10, 20, 30, 40 and t½/s = 0.70, 1.38, 2.08, 2.77. (a) Explain why a graph of t½ against R is a straight line through the origin. (b) Calculate the gradient using the first and last readings. (c) Calculate the capacitance, in µF. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '99.55', 'µF', false, NULL, false, ARRAY['9.955e-5']::text[], '(a) t½ = RC ln 2, so t½ ∝ R with gradient C ln 2. (b) Gradient = (2.77 − 0.70) ÷ ((40 − 10) × 10³) = 6.90 × 10⁻⁵ s Ω⁻¹. (c) C = gradient ÷ ln 2 = 6.900 × 10⁻⁵ ÷ ln 2 = 9.95 × 10⁻⁵ F. In µF: 9.955 × 10⁻⁵ × 10⁶ = 99.5. Mark scheme (6 marks). M1: t½ = RC ln 2. B1: proportional to R. C1: gradient. C1: C = gradient/ln 2. C1: conversion to µF. A1: C = 99.5 µF.', 6),
('e77dd16f-18d1-53bb-8c08-58655d798892', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 50, 50, 'In a pacemaker, a 2.0 µF capacitor charged to 5.0 V discharges through heart tissue of resistance 500 Ω. The pulse ends when the p.d. has fallen to 1.0 V. (a) Calculate the time constant. (b) Calculate the duration of the pulse, in ms. (c) Calculate the charge delivered during the pulse, in µC. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1.609 ms', 'ms', false, NULL, false, NULL, '(a) RC = 500 × 2.0 × 10⁻⁶ = 1.0 × 10⁻³ s. (b) V₀/V = 5, so t = RC ln 5 = 1.0 × 10⁻³ × ln 5 = 0.00161 s. In ms: 0.001609 × 1000 = 1.61. (c) ΔQ = C × ΔV = 2.0 × 10⁻⁶ × (5.0 − 1.0) = 8.0 × 10⁻⁶ C, which is 8.0 µC. Mark scheme (6 marks). C1: RC. M1: V/V₀ = 1/5. C1: t = RC ln 5. C1: conversion to ms. C1: ΔQ = CΔV. A1: t = 1.61 ms.', 6)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('c9eaa273-3a56-5bf1-bcfa-dfb2c70fa907', '96e990fc-60b8-585e-9f4f-8280e5a7c51b', 'A straight line falling to zero', 'A', false, 0),
('77ef3fae-edef-50c4-813f-c8d054df209b', '96e990fc-60b8-585e-9f4f-8280e5a7c51b', 'A constant current', 'B', false, 1),
('219736b4-a6a5-5ad0-ad18-f8874d1007bc', '96e990fc-60b8-585e-9f4f-8280e5a7c51b', 'An exponential decay curve', 'C', true, 2),
('7a85ceab-3e0c-536e-9d07-18e050be9820', '96e990fc-60b8-585e-9f4f-8280e5a7c51b', 'A curve that rises to a maximum', 'D', false, 3),
('6bc57e1e-2f39-5e09-9487-a4ad5d93b2a1', '55e5e9e0-7c6b-5852-b12f-c82be5a2ce4d', 'The time for the charge to fall to 1/e (about 37 %) of its initial value', 'A', true, 0),
('02c7f01f-592b-5584-9666-6eace339ea23', '55e5e9e0-7c6b-5852-b12f-c82be5a2ce4d', 'The time for the charge to fall to zero', 'B', false, 1),
('a18a58aa-06e8-5739-9eb9-2ea8e8ed31ce', '55e5e9e0-7c6b-5852-b12f-c82be5a2ce4d', 'The time for the charge to halve', 'C', false, 2),
('ca3920d3-5eef-532c-baf8-9add3e0eb203', '55e5e9e0-7c6b-5852-b12f-c82be5a2ce4d', 'The time for the charge to fall to 63 % of its initial value', 'D', false, 3),
('e8bdb0c1-51dc-5dc5-99f7-7fa53904bbba', '9582fc07-8f53-5456-8993-427088d63c0e', 'The capacitor discharges more quickly', 'A', false, 0),
('421f2c55-f911-5f3c-8440-c03eac34714c', '9582fc07-8f53-5456-8993-427088d63c0e', 'The initial charge increases', 'B', false, 1),
('ac105c97-3a96-5086-9037-040105df3cd1', '9582fc07-8f53-5456-8993-427088d63c0e', 'The discharge rate is unchanged', 'C', false, 2),
('e40c2df4-596c-5acc-8724-d07f2ba3fa04', '9582fc07-8f53-5456-8993-427088d63c0e', 'The capacitor discharges more slowly', 'D', true, 3),
('e8e218b2-15d5-5dc6-b618-f97b597a22e8', '1fb4f9e3-b3f5-5e2e-a17c-8b3c7d43091c', 'Ω F⁻¹', 'A', false, 0),
('d528b6d8-374a-5a3c-a3ad-d1a8d86c1f7d', '1fb4f9e3-b3f5-5e2e-a17c-8b3c7d43091c', 's', 'B', true, 1),
('8488e384-2c24-51f6-b755-9940a50214df', '1fb4f9e3-b3f5-5e2e-a17c-8b3c7d43091c', 'C V⁻¹', 'C', false, 2),
('912c539c-acc2-5a6f-a5b9-815a038fa5a0', '1fb4f9e3-b3f5-5e2e-a17c-8b3c7d43091c', 'A', 'D', false, 3),
('d494c8a2-541e-532c-af9a-ed1788232701', 'e50ce724-5e25-5b03-8c52-7f3d89614e7b', 'A straight line with gradient −RC', 'A', false, 0),
('2675c9ea-4ce9-5ced-91a8-b8c5536cf25a', 'e50ce724-5e25-5b03-8c52-7f3d89614e7b', 'An exponential curve', 'B', false, 1),
('aea96cdd-dc6c-550c-8ed6-beb8d0e67ad0', 'e50ce724-5e25-5b03-8c52-7f3d89614e7b', 'A straight line with gradient −1/RC', 'C', true, 2),
('3425cc50-0965-533d-b2ce-7be110fc559b', 'e50ce724-5e25-5b03-8c52-7f3d89614e7b', 'A horizontal line', 'D', false, 3),
('cd7be067-2fbc-5217-ba1e-2d51cece70a5', 'a360e909-dabf-57fc-9abd-e95fbe4cc8a3', 'The discharge is exponential', 'A', true, 0),
